  const remainder = (numerator * 100) % denominator;
  if (2 * remainder > denominator || (2 * remainder === denominator && hundredths % 2 === 1)) {
    hundredths += 1;
  }
  return hundredths;
};
const expectedWithout = roundHundredths(slots.probabilityPercent * slots.loss, 100);
